{
  "mechanisms": [
    {
      "name": "load_scaled_wm_weight",
      "title": "Load-Scaled WM Weight",
      "description": "The base working memory mixture weight is scaled down by a power law of the set size relative to the minimum load.",
      "params": [
        {
          "name": "load_beta",
          "bounds": [0, null]
        }
      ],
      "evidence": "load_scale = (3.0 / float(nS)) ** max(0.0, load_beta)\n        wm_weight_block = max(0.0, min(1.0, wm_weight * min(1.0, load_scale)))",
      "expressible_in_slots": true
    },
    {
      "name": "surprise_confidence_wm_boost",
      "title": "Surprise and Confidence Gated WM Arbitration",
      "description": "The trial-by-trial working memory mixture weight is dynamically boosted by the product of the absolute RL prediction error (surprise) and the confidence of the WM state (difference between top two action weights).",
      "params": [
        {
          "name": "surprise_gate",
          "bounds": [0, null]
        }
      ],
      "evidence": "sorted_W = np.sort(W_s)[::-1]\n            conf = max(0.0, sorted_W[0] - (sorted_W[1] if len(sorted_W) > 1 else 0.0))\n            wm_boost = surprise_gate * abs(pe) * conf\n            wm_weight_t = max(0.0, min(1.0, wm_weight_block + wm_boost))",
      "expressible_in_slots": true
    },
    {
      "name": "prob_preserving_wm_update",
      "title": "Probability-Preserving WM Update",
      "description": "Working memory updates maintain a probability distribution by shifting mass toward the chosen action on reward, and distributing mass from the chosen action equally to unchosen actions on error, followed by a normalization step.",
      "params": [
        {
          "name": "wm_alpha",
          "bounds": [0, 1]
        }
      ],
      "evidence": "if r > 0.5:\n\n                w[s, :] = (1.0 - wm_alpha) * w[s, :]\n                w[s, a] += wm_alpha\n            else:\n\n                reduce = wm_alpha * min(1.0, w[s, a])\n                w[s, a] = max(0.0, w[s, a] - reduce)\n                increment = reduce / (nA - 1)\n                for aa in range(nA):\n                    if aa != a:\n                        w[s, aa] += increment\n\n            row_sum = np.sum(w[s, :])\n            if row_sum > 0:\n                w[s, :] /= row_sum\n            else:\n                w[s, :] = w_0[s, :]",
      "expressible_in_slots": true
    }
  ]
}
